&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1553&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT\n    pNou.Id,\n    pNou.Marca,\n    s.Nume AS NumeSalariat,\n    pNou.CNPAltaPersoana,\n    pNou.NumeAltaPersoana,\n    pNou.PrenumeAltaPersoana,\n\n    pVechi.FelPersoanaVeche,\n    pNou.FelPersoana AS FelPersoanaNoua,\n\n    pVechi.DataDeSfarsitVeche,\n    pNou.DataDeInceput AS DataDeInceputNoua,\n\n    pNou.Grad,\n    pNou.Procent AS ProcentNou,\n    pNou.DataNasteriiCopil\n\nFROM app.PersoanaIntretinere pNou\n\nINNER JOIN app.Salariat s\n    ON s.CodSucursala = pNou.CodSucursala\n   AND s.Marca = pNou.Marca\n\nCROSS APPLY\n(\n    SELECT TOP (1)\n        pVechi.FelPersoana AS FelPersoanaVeche,\n        pVechi.DataDeSfarsit AS DataDeSfarsitVeche\n    FROM app.PersoanaIntretinere pVechi\n    WHERE pVechi.CodSucursala = pNou.CodSucursala\n      AND pVechi.Marca = pNou.Marca\n      AND LTRIM(RTRIM(pVechi.CNPAltaPersoana)) =\n          LTRIM(RTRIM(pNou.CNPAltaPersoana))\n      AND pVechi.FelPersoana IN (&#39;2&#39;, &#39;3&#39;)\n      AND pVechi.DataDeSfarsit =\n          EOMONTH\n          (\n              DATEADD\n              (\n                  MONTH,\n                  -1,\n                  DATEFROMPARTS(CONVERT(INT, @Anul), CONVERT(INT, @Luna), 1)\n              )\n          )\n    ORDER BY pVechi.Id DESC\n) pVechi\n\nWHERE pNou.CodSucursala = @CodSucursala\n  AND pNou.FelPersoana = &#39;4&#39;\n  AND pNou.DataDeInceput =\n      DATEFROMPARTS(CONVERT(INT, @Anul), CONVERT(INT, @Luna), 1)\n\nORDER BY\n    pNou.Marca,\n    pNou.CNPAltaPersoana;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Marca&quot;,&quot;Name&quot;:&quot;Marca&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;NumeSalariat&quot;,&quot;Name&quot;:&quot;NumeSalariat&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CNPAltaPersoana&quot;,&quot;Name&quot;:&quot;CNPAltaPersoana&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title